# ── Site detection ───────────────────────────────────────────────────────────

def get_site_base(url: str) -> str:
    """Return the canonical base URL for the site the given URL belongs to."""
    parsed = urlparse(url)
    netloc = parsed.netloc.lower().lstrip("www.")
    for key, base in SUPPORTED_SITES.items():
        if netloc == key or netloc.endswith("." + key):
            return base
    # Unknown site — use the scheme+host from the URL itself so the script
    # can still attempt a best-effort generic download.
    return f"{parsed.scheme}://{parsed.netloc}"


# ── azgames.io helpers ───────────────────────────────────────────────────────

def _scrape_azgames(page_url: str, base: str) -> str:
    """
    azgames.io embeds games in a few different ways:
      1. An <iframe> whose src is the direct game URL (most common).
      2. A data attribute or JS variable pointing at the game bundle.
    We try them in order and fall back to the generic iframe scraper.
    """
    resp = requests.get(page_url, timeout=10)
    resp.raise_for_status()
    soup = BeautifulSoup(resp.text, "html.parser")

    # Strategy 1 – <iframe>
    iframe = soup.find("iframe")
    if iframe and iframe.get("src"):
        src = iframe["src"]
        if src.startswith("//"):
            src = "https:" + src
        if not src.startswith("http"):
            src = urljoin(base, src)
        return src

    # Strategy 2 – <div data-game-url="..."> or similar data attributes
    for tag in soup.find_all(True):
        for attr in ("data-game-url", "data-src", "data-url"):
            val = tag.get(attr)
            if val and ("game" in val.lower() or val.endswith((".html", ".htm"))):
                if not val.startswith("http"):
                    val = urljoin(base, val)
                return val

    # Strategy 3 – JS variable assignment like gameUrl = "..."
    for script in soup.find_all("script"):
        text = script.string or ""
        m = re.search(r'(?:gameUrl|game_url|embedUrl|embed_url)\s*[=:]\s*["\']([^"\']+)["\']', text, re.I)
        if m:
            val = m.group(1)
            if not val.startswith("http"):
                val = urljoin(base, val)
            return val

    raise ValueError(f"Could not find a game embed on: {page_url}")


# ── Generic helpers (previously hard-coded to truffled.lol) ─────────────────

def extract_game_url(page_url: str, base: str) -> str:
    parsed = urlparse(page_url)
    qs = parse_qs(parsed.query)
    if "url" in qs:
        inner = unquote(qs["url"][0])
        inner_qs = parse_qs(urlparse(inner).query)
        if "url" in inner_qs:
            inner = unquote(inner_qs["url"][0])
        return base + inner
    return page_url if page_url.startswith("http") else base + page_url


def scrape_game_url_from_page(page_url: str, base: str) -> str:
    resp = requests.get(page_url, timeout=10)
    resp.raise_for_status()
    soup = BeautifulSoup(resp.text, "html.parser")
    iframe = soup.find("iframe")
    if not iframe or not iframe.get("src"):
        raise ValueError("Could not find an iframe on the page.")
    return extract_game_url(urljoin(base, iframe["src"]), base)


def resolve_game_url(user_url: str, base: str) -> str:
    parsed = urlparse(user_url)
    netloc = parsed.netloc.lower().lstrip("www.")

    # azgames.io — always scrape the listing page
    if "azgames.io" in netloc:
        return _scrape_azgames(user_url, base)

    # truffled.lol (and unknown sites) — original logic
    if "iframe.html" in parsed.path or "mobile.html" in parsed.path:
        return extract_game_url(user_url, base)
    if parsed.path.startswith("/gamefile/") or re.match(r"^/games/", parsed.path):
        return extract_game_url(user_url, base)
    return scrape_game_url_from_page(user_url, base)


def parse_ejs_config(html: str) -> dict:
    config = {}
    for m in re.finditer(r'EJS_(\w+)\s*=\s*["\']([^"\']+)["\']', html):
        config[m.group(1)] = m.group(2)
    return config


def is_old_style_loader(loader_text: str) -> bool:
    return "createElement" in loader_text and "import(" not in loader_text


def ejs_already_downloaded(data_dir: Path) -> bool:
    if (data_dir / SENTINEL_FILE).exists():
        return True
    if (data_dir / "emulator.js").exists():
        return True
    return False


def download_ejs_sources(data_dir: Path, force: bool = False):
    if not force and ejs_already_downloaded(data_dir):
        print(f"  [~] EmulatorJS already present in {data_dir}, skipping.")
        return

    print(f"[*] Downloading EmulatorJS {EJS_TAG} source files from GitHub ...")
    data_dir.mkdir(parents=True, exist_ok=True)

    failed = []
    for rel_path in EJS_SOURCE_FILES:
        dest = data_dir / rel_path
        if dest.exists() and not force:
            continue
        dest.parent.mkdir(parents=True, exist_ok=True)
        try:
            resp = requests.get(f"{EJS_RAW}/{rel_path}", timeout=30)
            resp.raise_for_status()
            dest.write_bytes(resp.content)
            print(f"  [+] {rel_path}")
        except Exception as e:
            print(f"  [!] Failed: {rel_path} — {e}")
            failed.append(rel_path)

    nipple_dest = data_dir / "nipplejs.js"
    if not nipple_dest.exists() or force:
        try:
            resp = requests.get(f"{EJS_RAW}/nipplejs.js", timeout=30)
            resp.raise_for_status()
            patched_content = resp.content.decode("utf-8", errors="ignore") + NIPPLEJS_RESCUE
            nipple_dest.write_text(patched_content, encoding="utf-8")
            print("  [+] nipplejs.js (patched: window.nipplejs rescue appended)")
        except Exception as e:
            print(f"  [!] Failed: nipplejs.js — {e}")
            failed.append("nipplejs.js")

    en_json = data_dir / "localization" / "en.json"
    en_us_json = data_dir / "localization" / "en-US.json"
    if en_json.exists() and (not en_us_json.exists() or force):
        en_us_json.write_bytes(en_json.read_bytes())
        print("  [+] localization/en-US.json (copied from en.json)")

    emulator_js = data_dir / "emulator.js"
    min_js = data_dir / "emulator.min.js"
    min_css = data_dir / "emulator.min.css"

    if emulator_js.exists() and (not min_js.exists() or force):
        min_js.write_bytes(emulator_js.read_bytes())
        print("  [+] emulator.min.js (copied from emulator.js)")

    if not min_css.exists() or force:
        min_css.write_text("@import url('emulator.css');\n", encoding="utf-8")
        print("  [+] emulator.min.css (shim)")

    if not failed:
        (data_dir / SENTINEL_FILE).write_text(EJS_TAG, encoding="utf-8")
        print(f"  [✓] EmulatorJS source files ready in {data_dir}")
    else:
        print(f"  [!] Completed with {len(failed)} failure(s): {failed}")

    patch_emulatorjs_canvas_resize(data_dir)


def patch_emulatorjs_canvas_resize(data_dir: Path):
    """Backfill a safe resize path for EmulatorJS builds that lack setCanvasSize."""
    replacement = """        const dpr = window.devicePixelRatio || 1;
        const width = positionInfo.width * dpr;
        const height = (positionInfo.height * dpr);
        if (typeof this.Module.setCanvasSize === "function") {
            this.Module.setCanvasSize(width, height);
        } else if (this.Module.canvas) {
            this.Module.canvas.width = width;
            this.Module.canvas.height = height;
        }
        if (!this.handleSettingsResize) return;"""

    for rel_path in ["emulator.js", "emulator.min.js"]:
        target = data_dir / rel_path
        if not target.exists():
            continue
        try:
            text = target.read_text(encoding="utf-8", errors="ignore")
            old = """        const dpr = window.devicePixelRatio || 1;
        const width = positionInfo.width * dpr;
        const height = (positionInfo.height * dpr);
        this.Module.setCanvasSize(width, height);
        if (!this.handleSettingsResize) return;"""
            if old in text:
                patched = text.replace(old, replacement)
                if patched != text:
                    target.write_text(patched, encoding="utf-8")
                    print(f"  [~] Patched resize compatibility in {target.relative_to(data_dir)}")
        except Exception:
            pass


def resolve_rom_url(ejs_game_url: str, base_game_url: str, base: str) -> str:
    if ejs_game_url.startswith("http"):
        return ejs_game_url
    if ejs_game_url.startswith("/"):
        return base + ejs_game_url
    return urljoin(base_game_url, ejs_game_url)


def download_rom(rom_url: str, out_dir: Path) -> Path | None:
    rom_filename = rom_url.split("?")[0].rsplit("/", 1)[-1]
    rom_path = out_dir / rom_filename
    if rom_path.exists():
        print(f"  [~] ROM already exists: {rom_path.name}")
        return rom_path

    print(f"[*] Downloading ROM: {rom_url}")
    try:
        with requests.get(rom_url, timeout=300, stream=True) as resp:
            resp.raise_for_status()
            total = int(resp.headers.get("content-length", 0))
            downloaded = 0
            with open(rom_path, "wb") as f:
                for chunk in resp.iter_content(chunk_size=65536):
                    f.write(chunk)
                    downloaded += len(chunk)
                    if total:
                        pct = downloaded * 100 // total
                        mb = downloaded / (1024 * 1024)
                        print(f"\r  [~] {pct:3d}%  {mb:.1f} / {total / (1024*1024):.1f} MB", end="", flush=True)
        print()
        print(f"  [+] ROM saved: {rom_path.name}")
        return rom_path
    except Exception as e:
        print(f"  [!] Failed to download ROM: {e}")
        return None


