def patch_index_ruffle(index_path: Path, swf_filename: str):
    """
    Rewrite the index.html for a Ruffle/Flash game so it loads from the
    self-hosted CDN instead of the missing /js/main.js reference, and
    points Ruffle at the locally-saved SWF.
    """
    html = index_path.read_text(encoding="utf-8", errors="ignore")

    html = re.sub(r'<script[^>]+src=["\'][^"\']*\/js\/main\.js["\'][^>]*>\s*<\/script>', '', html)
    html = re.sub(r'<script[^>]+src=["\'][^"\']*ruffle[^"\']*["\'][^>]*>\s*<\/script>', '', html, flags=re.IGNORECASE)
    html = re.sub(r'<script[^>]*>.*?RufflePlayer.*?</script>', '', html, flags=re.DOTALL | re.IGNORECASE)

    ruffle_snippet = f"""<script src="ruffle.js"></script>
<script>
  window.addEventListener("load", function () {{
    var player = window.RufflePlayer.newest().createPlayer();
    player.style.width  = "100%";
    player.style.height = "100vh";
    document.body.appendChild(player);
    player.load("{swf_filename}");
  }});
</script>"""

    if "</body>" in html:
        html = html.replace("</body>", ruffle_snippet + "\n</body>")
    else:
        html += "\n" + ruffle_snippet

    index_path.write_text(html, encoding="utf-8")
    print(f"  [~] Patched index.html (Ruffle):")
    print(f"       SWF             → {swf_filename}")
    print(f"       Ruffle loader   → ruffle.js (self-hosted)")
    print(f"       /js/main.js     → removed (site-only, not needed)")


def get_game_name(game_index_url: str) -> str:
    try:
        resp = requests.get(game_index_url, timeout=10)
        soup = BeautifulSoup(resp.text, "html.parser")
        title = soup.find("title")
        if title and title.text.strip():
            name = re.sub(r'[\\/*?:"<>|]', "", title.text.strip())
            return name.strip().lower().replace(" ", "_")
    except Exception:
        pass
    parts = [p for p in urlparse(game_index_url).path.split("/") if p]
    for part in reversed(parts):
        if part != "index.html":
            return part.lower()
    return "unknown_game"


# ── Asset-discovery helpers ──────────────────────────────────────────────────

_ASSET_EXTS = r"wasm|data|ogg|mp3|wav|png|jpg|jpeg|gif|svg|ttf|woff2?|json|lua|lovejs|love|swf|iso|map"


def _is_allowed_origin(url: str, allowed_origins: list[str]) -> bool:
    """Return True if url's origin matches any of the allowed_origins prefixes."""
    return any(url.startswith(o) for o in allowed_origins)


def collect_assets_from_text(text: str, base_url: str, base_game_url: str, url_to_local_path, allowed_origins: list[str]) -> list:
    assets = []

    for match in re.findall(r'url\(["\']?([^"\')\s]+)["\']?\)', text):
        if not match.startswith(("http", "data:", "#")):
            full = urljoin(base_url, match.split("?")[0])
            if _is_allowed_origin(full, allowed_origins):
                assets.append((full, url_to_local_path(full)))

    for match in re.findall(
        rf'["\`\'][\w./\-]+\.(?:{_ASSET_EXTS})["\`\']',
        text,
        flags=re.IGNORECASE,
    ):
        clean = match.strip("\"'`").split("?")[0]
        if not clean.startswith(("http", "data:", "#")):
            full = urljoin(base_url, clean)
            if _is_allowed_origin(full, allowed_origins):
                assets.append((full, url_to_local_path(full)))

    for match in re.findall(r'["\']([^"\']*game\.[a-z0-9]+)["\']', text, flags=re.IGNORECASE):
        clean = match.split("?")[0]
        if not clean.startswith(("http", "data:", "#")):
            full = urljoin(base_url, clean)
            if _is_allowed_origin(full, allowed_origins):
                assets.append((full, url_to_local_path(full)))

    return assets


def asset_url_candidates(url: str) -> list[str]:
    """Return alternate URLs worth trying when the first fetch returns 404."""
    clean_url = url.split("#", 1)[0].split("?", 1)[0]
    parsed = urlparse(clean_url)
    path = parsed.path

    candidates = [clean_url]

    if "/static/js/" in path:
        candidates.append(clean_url.replace("/static/js/", "/", 1))
    if "/static/css/" in path:
        candidates.append(clean_url.replace("/static/css/", "/", 1))

    deduped = []
    seen = set()
    for candidate in candidates:
        if candidate not in seen:
            seen.add(candidate)
            deduped.append(candidate)
    return deduped


def is_optional_asset(url: str) -> bool:
    return urlparse(url).path in OPTIONAL_ROOT_ASSETS


def strip_redirects_from_html(html: str, game_origin: str) -> tuple[str, int]:
    """
    Remove JS and meta-refresh redirects that would send the browser back to
    the live site when the page is opened locally.  Returns (patched_html, count).
    """
    count = 0

    # <meta http-equiv="refresh" content="...">
    before = html
    html = re.sub(r'<meta[^>]+http-equiv=["\']refresh["\'][^>]*>', '', html, flags=re.IGNORECASE)
    if html != before:
        count += html.count("refresh") + 1  # rough

    # window.location / document.location assignments pointing off-origin
    def _kill_location(m):
        nonlocal count
        target = m.group(1)
        parsed = urlparse(target)
        if parsed.scheme in ("http", "https") and not target.startswith(game_origin):
            count += 1
            return f"/* luv.py: redirect removed */ void(0); //{m.group(0)}"
        return m.group(0)

    html = re.sub(
        r'(?:window|document|top|self|parent)\.location(?:\.href)?\s*=\s*["\']([^"\']+)["\']',
        _kill_location,
        html,
    )

    # location.replace("...") / location.assign("...")
    def _kill_location_fn(m):
        nonlocal count
        target = m.group(2)
        parsed = urlparse(target)
        if parsed.scheme in ("http", "https") and not target.startswith(game_origin):
            count += 1
            return f"/* luv.py: redirect removed */ void(0); //{m.group(0)}"
        return m.group(0)

    html = re.sub(
        r'(?:window\.)?location\.(replace|assign)\(["\']([^"\']+)["\']\)',
        _kill_location_fn,
        html,
    )

    return html, count


def rewrite_local_asset_refs_in_text(text: str, out_path: Path, base_game_path: str) -> str:
    """Rewrite root-absolute local asset refs to relative paths when possible."""

    def replace_attr(match):
        url = match.group("url")
        clean = url.split("#", 1)[0].split("?", 1)[0]
        if clean.startswith(base_game_path):
            local_path = out_path / clean[len(base_game_path):]
        else:
            local_path = out_path / clean.lstrip("/")
        if clean.startswith("/") and local_path.exists():
            rel_path = local_path.relative_to(out_path).as_posix()
            return f'{match.group("prefix")}{rel_path}{match.group("suffix")}'
        return match.group(0)

    def replace_css_url(match):
        url = match.group("url")
        clean = url.split("#", 1)[0].split("?", 1)[0]
        if clean.startswith(base_game_path):
            local_path = out_path / clean[len(base_game_path):]
        else:
            local_path = out_path / clean.lstrip("/")
        if clean.startswith("/") and local_path.exists():
            quote = match.group("quote") or ""
            rel_path = local_path.relative_to(out_path).as_posix()
            return f'url({quote}{rel_path}{quote})'
        return match.group(0)

    text = re.sub(
        r'(?P<prefix>\b(?:src|href)=["\'])(?P<url>/[^"\']+)(?P<suffix>["\'])',
        replace_attr,
        text,
    )
    text = re.sub(
        r'url\((?P<quote>["\']?)(?P<url>/[^)"\']+)(?P=quote)\)',
        replace_css_url,
        text,
    )
    return text


def rewrite_local_asset_refs_in_tree(out_path: Path, base_game_path: str):
    updated = 0
    for file_path in out_path.rglob("*"):
        if file_path.suffix.lower() not in {".html", ".htm", ".css"}:
            continue
        try:
            text = file_path.read_text(encoding="utf-8", errors="ignore")
            rewritten = rewrite_local_asset_refs_in_text(text, out_path, base_game_path)
            if rewritten != text:
                file_path.write_text(rewritten, encoding="utf-8")
                updated += 1
        except Exception:
            pass
    if updated:
        print(f"  [~] Rewrote {updated} HTML/CSS file(s) to use local asset paths")


def ensure_placeholder_manifest(index_html: str, out_path: Path, game_name: str):
    """Create a local manifest.json when the page references one but none exists."""
    if "manifest.json" not in index_html.lower():
        return

    manifest_path = out_path / "manifest.json"
    if manifest_path.exists():
        return

    manifest = {
        "name": game_name.replace("_", " ").title(),
        "short_name": game_name[:12],
        "start_url": ".",
        "display": "standalone",
        "background_color": "#000000",
        "theme_color": "#000000",
    }

    import json
    manifest_path.write_text(json.dumps(manifest, indent=2), encoding="utf-8")
    print("  [+] manifest.json (generated placeholder)")


def download_ejs_core_assets(core: str, data_dir: Path):
    """Mirror core-specific EmulatorJS assets locally when we know the core."""
    core = (core or "").lower()
    if core not in {"psp", "ppsspp"}:
        return

    core_dir = data_dir / "cores"
    core_dir.mkdir(parents=True, exist_ok=True)

    for rel_path in PPSPP_CORE_ASSETS:
        dest = core_dir / rel_path
        if dest.exists():
            continue
        url = f"{EJS_CDN_CORES}cores/{rel_path}"
        try:
            resp = requests.get(url, timeout=60)
            resp.raise_for_status()
            dest.write_bytes(resp.content)
            print(f"  [+] cores/{rel_path}")
        except Exception as e:
            print(f"  [!] Failed: cores/{rel_path} — {e}")


def find_swf_in_html(html: str, base_game_url: str) -> str | None:
    soup = BeautifulSoup(html, "html.parser")

    param = soup.find("param", attrs={"name": re.compile(r"movie", re.I)})
    if param and param.get("value"):
        return urljoin(base_game_url, param["value"])

    m = re.search(r'["\']([^"\']*\.swf)["\']', html, re.IGNORECASE)
    if m:
        return urljoin(base_game_url, m.group(1).split("?")[0])

    m = re.search(r'\.load\(["\']([^"\']+\.swf)["\']', html, re.IGNORECASE)
    if m:
        return urljoin(base_game_url, m.group(1).split("?")[0])

    tag = soup.find(src=re.compile(r"\.swf", re.I))
    if tag:
        return urljoin(base_game_url, tag["src"].split("?")[0])

    return None


def is_ruffle_game(html: str, soup: BeautifulSoup) -> bool:
    """Return True when the page uses Ruffle (Flash emulator)."""
    if soup.find("script", src=re.compile(r"ruffle", re.I)):
        return True
    if re.search(r"RufflePlayer|ruffle\.js", html, re.I):
        return True
    if soup.find(attrs={"type": re.compile(r"application/x-shockwave-flash", re.I)}):
        return True
    return False


# ── Main download orchestration ──────────────────────────────────────────────

def download_game(game_index_url: str, out_base: str = "./exported", site_base: str = _DEFAULT_BASE):
    print(f"[*] Resolved game URL: {game_index_url}")
    print(f"[*] Site base: {site_base}")
    game_name = get_game_name(game_index_url)
    print(f"[*] Game name: {game_name}")

    base_game_url = game_index_url.rsplit("/", 1)[0] + "/"

    # The game may be hosted on a different origin than the referring site
    # (e.g. azgames.io listing → gamea.azgame.io game host).  Build a list of
    # all origins we're allowed to pull assets from.
    _parsed_game = urlparse(game_index_url)
    game_origin = f"{_parsed_game.scheme}://{_parsed_game.netloc}"
    allowed_origins: list[str] = list({site_base, game_origin})  # deduplicate
    print(f"[*] Allowed asset origins: {allowed_origins}")

    out_path = Path(out_base) / game_name
    out_path.mkdir(parents=True, exist_ok=True)

    visited = set()
    base_game_path = urlparse(base_game_url).path

    def url_to_local_path(url: str) -> Path:
        clean_url = url.split("?", 1)[0].split("#", 1)[0]
        clean_path = urlparse(clean_url).path
        if clean_path.startswith(base_game_path):
            rel = clean_path[len(base_game_path):]
        else:
            rel = clean_path.lstrip("/")
        return out_path / rel

    def fetch_and_save(url: str, save_path: Path | None = None, silent_404: bool = False, preserve_path: bool = False):
        last_error = None
        for candidate_url in asset_url_candidates(url):
            if candidate_url in visited:
                continue
            visited.add(candidate_url)
            target_path = save_path if preserve_path and save_path is not None else url_to_local_path(candidate_url)
            try:
                resp = requests.get(candidate_url, timeout=60)
                resp.raise_for_status()
            except requests.HTTPError as e:
                last_error = e
                continue
            except Exception as e:
                last_error = e
                continue
            target_path.parent.mkdir(parents=True, exist_ok=True)
            target_path.write_bytes(resp.content)
            display_url = candidate_url.replace(site_base, "")
            print(f"  [+] {display_url} -> {target_path.relative_to(out_path)}")
            return resp
        if last_error and not silent_404 and not is_optional_asset(url):
            print(f"  [!] Failed to fetch {url}: {last_error}")
        return None

    # ── Download index.html ──────────────────────────────────────────────────
    index_resp = fetch_and_save(game_index_url, out_path / "index.html", preserve_path=True)
    if not index_resp:
        raise RuntimeError("Failed to download game index.html")

    html_text = index_resp.text

    # Strip JS/meta redirects that would bounce the browser back to the live site
    html_text, n_stripped = strip_redirects_from_html(html_text, game_origin)
    if n_stripped:
        (out_path / "index.html").write_text(html_text, encoding="utf-8")
        print(f"  [~] Stripped {n_stripped} redirect(s) from index.html")

    soup = BeautifulSoup(html_text, "html.parser")
    ensure_placeholder_manifest(html_text, out_path, game_name)

    # ── EmulatorJS branch ────────────────────────────────────────────────────
    ejs_config = parse_ejs_config(html_text)
    is_emulatorjs = bool(ejs_config.get("gameUrl") or ejs_config.get("core"))

    if is_emulatorjs:
        core = ejs_config.get("core", "unknown")
        print(f"[*] Detected EmulatorJS game (core: {core})")

        loader_url = urljoin(base_game_url, "loader.js")
        loader_resp = fetch_and_save(loader_url, out_path / "loader.js", preserve_path=True)
        loader_text = loader_resp.content.decode("utf-8", errors="ignore") if loader_resp else ""

        data_dir = out_path / "data"

        if is_old_style_loader(loader_text):
            print(f"[*] Loader style: classic script (4.0.9)")
            download_ejs_sources(data_dir)
        else:
            print(f"[*] Loader style: ES module (new) — CDN zip needed")
            print(f"  [!] Download emulator.min.zip manually:")
            print(f"      https://cdn.emulatorjs.org/stable/data/emulator.min.zip")
            print(f"      Extract to: {data_dir}")

        download_ejs_core_assets(core, data_dir)

        rom_url_raw = ejs_config.get("gameUrl", "")
        if rom_url_raw:
            rom_url = resolve_rom_url(rom_url_raw, base_game_url, site_base)
            rom_path = download_rom(rom_url, out_path)
            if rom_path:
                patch_index_emulatorjs(out_path / "index.html", rom_path.name, ejs_config)
        else:
            print("  [!] EJS_gameUrl not found — set it manually in index.html")

        rewrite_local_asset_refs_in_tree(out_path, base_game_path)

        print(f"\n[✓] {out_path.resolve()}")
        if core == "ppsspp":
            print(f"    Note: PPSSPP core streams from CDN on first launch (~60 MB)")
        return

    # ── Ruffle / Flash branch ────────────────────────────────────────────────
    if is_ruffle_game(html_text, soup):
        print("[*] Detected Ruffle (Flash) game")

        swf_url = find_swf_in_html(html_text, base_game_url)

        if not swf_url:
            for candidate in ["swf.swf", "game.swf", "flash.swf", "index.swf"]:
                test_url = base_game_url + candidate
                try:
                    r = requests.head(test_url, timeout=10)
                    if r.status_code == 200:
                        swf_url = test_url
                        print(f"  [~] SWF found via HEAD probe: {candidate}")
                        break
                except Exception:
                    pass

        if swf_url:
            swf_filename = swf_url.split("?")[0].rsplit("/", 1)[-1]
            swf_path = out_path / swf_filename
            print(f"[*] Downloading SWF: {swf_url.replace(site_base, '')}")
            resp = fetch_and_save(swf_url, swf_path, preserve_path=True)
            if not resp:
                print("  [!] SWF download failed — game may not work offline")
        else:
            swf_filename = "game.swf"
            print(f"  [!] Could not auto-detect SWF URL; set it manually in index.html")

        ruffle_dest = out_path / "ruffle.js"
        if not ruffle_dest.exists():
            print(f"[*] Downloading Ruffle from {RUFFLE_CDN} ...")
            try:
                r = requests.get(RUFFLE_CDN, timeout=30)
                r.raise_for_status()
                ruffle_dest.write_bytes(r.content)
                print("  [+] ruffle.js")
            except Exception as e:
                print(f"  [~] Ruffle CDN fetch skipped ({e}); will use page's ruffle.js")

        patch_index_ruffle(out_path / "index.html", swf_filename)

        _download_generic_assets(
            soup, html_text, base_game_url, out_path, url_to_local_path, fetch_and_save, allowed_origins
        )

        rewrite_local_asset_refs_in_tree(out_path, base_game_path)

        print(f"\n[✓] {out_path.resolve()}")
        return

    # ── Generic HTML5 game branch ────────────────────────────────────────────
    print("[*] Detected generic HTML5 game")
    _download_generic_assets(
        soup, html_text, base_game_url, out_path, url_to_local_path, fetch_and_save, allowed_origins
    )

    rewrite_local_asset_refs_in_tree(out_path, base_game_path)

    for fname in ["game.data", "game.wasm", "game.swf"]:
        explicit_path = out_path / fname
        if not explicit_path.exists():
            print(f"[*] Explicitly trying {fname}...")
            fetch_and_save(base_game_url + fname, explicit_path, silent_404=True, preserve_path=True)

    rewrite_local_asset_refs_in_tree(out_path, base_game_path)

    print(f"\n[✓] {out_path.resolve()}")


def _download_generic_assets(soup, html_text, base_game_url, out_path, url_to_local_path, fetch_and_save, allowed_origins: list[str]):
    """Download all linked assets found in a page's HTML and recurse into JS/CSS."""
    assets = []

    for tag in soup.find_all(["script", "link", "img", "source", "audio", "video"]):
        for attr in ["src", "href", "data-src"]:
            val = tag.get(attr)
            if val and not val.startswith(("http", "//", "data:", "#", "javascript:")):
                full = urljoin(base_game_url, val.split("?")[0])
                if _is_allowed_origin(full, allowed_origins):
                    assets.append((full, url_to_local_path(full)))
            elif val and val.startswith("//"):
                full = "https:" + val.split("?")[0]
                if _is_allowed_origin(full, allowed_origins):
                    assets.append((full, url_to_local_path(full)))
            elif val and val.startswith("http"):
                full = val.split("?")[0]
                if _is_allowed_origin(full, allowed_origins):
                    assets.append((full, url_to_local_path(full)))

    assets += collect_assets_from_text(html_text, base_game_url, base_game_url, url_to_local_path, allowed_origins)
    print(f"[*] Found {len(assets)} initial assets...")

    for url, path in assets:
        resp = fetch_and_save(url, path)
        if not resp:
            continue
        if url.split("?")[0].rsplit(".", 1)[-1].lower() in ("css", "js"):
            try:
                text = resp.content.decode("utf-8", errors="ignore")
                for n_url, n_path in collect_assets_from_text(
                    text, url.rsplit("/", 1)[0] + "/", base_game_url, url_to_local_path, allowed_origins
                ):
                    fetch_and_save(n_url, n_path)
            except Exception:
                pass

    for js_file in out_path.rglob("*.js"):
        try:
            text = js_file.read_text(encoding="utf-8", errors="ignore")
            patched = re.sub(r'(\.(data|wasm|ogg|mp3|wav|png|jpg|json|love|css|swf))\?[^"\'&\s]+', r'\1', text)
            if patched != text:
                js_file.write_text(patched, encoding="utf-8")
                print(f"  [~] Patched cache busters in {js_file.relative_to(out_path)}")
        except Exception:
            pass


def run(url: str, out_base: str = "./exported"):
    site_base = get_site_base(url)
    netloc = urlparse(url).netloc.lower().lstrip("www.")

    known = any(netloc == k or netloc.endswith("." + k) for k in SUPPORTED_SITES)
    if not known:
        print(f"[!] Warning: '{netloc}' is not a recognised site. Attempting best-effort download.")

    game_url = resolve_game_url(url, site_base)
    download_game(game_url, out_base=out_base, site_base=site_base)